import { CommonModule } from '@angular/common';
import { Component, OnInit, OnDestroy } from '@angular/core';
import { RouterModule } from '@angular/router';
import { TranslateModule, TranslateService } from '@ngx-translate/core';
import { ApiService, Experience } from '../../../../services/api';
import { Observable, Subscription } from 'rxjs';

@Component({
  selector: 'app-expeciencie',
  standalone: true,
  imports: [CommonModule, RouterModule, TranslateModule],
  templateUrl: './expeciencie.component.html',
  styleUrl: './expeciencie.component.css'
})
export class ExpeciencieComponent implements OnInit, OnDestroy {
  showFullProjects = false;
  $experiences: Observable<Experience[]> = new Observable();
  private langChangeSubscription?: Subscription;

  constructor(
    private translate: TranslateService,
    private apiService: ApiService
  ) {}

  ngOnInit() {
    this.loadExperiences();

    // Recargar cuando el idioma cambie
    this.langChangeSubscription = this.translate.onLangChange.subscribe(() => {
      this.loadExperiences();
    });
  }

  ngOnDestroy() {
    if (this.langChangeSubscription) {
      this.langChangeSubscription.unsubscribe();
    }
  }

  loadExperiences() {
    this.$experiences = this.apiService.getExperience();
  }

  toggleFullProjects() {
    this.showFullProjects = !this.showFullProjects;
  }

  changeLang(language: string) {
    this.translate.use(language);
  }
}
<section id="experience-section">
  <div class="experience-card">
    <h2>{{'EXPERIENCIA.TITLE' | translate}}</h2>
    <div *ngFor="let exp of $experiences | async" class="experience-item">
      <h3>{{ exp.position }}</h3>

      <!-- Contenedor para fecha y subtítulo en la misma línea -->
      <div class="subtitle-date">
        <h5>{{ exp.company }}</h5>
        <strong>{{ exp.period }}</strong>
      </div>

      <p *ngFor="let desc of exp.description">{{ desc }}</p>
      <div class="technologies">
        <span *ngFor="let tech of exp.technologies" class="tech-tag">{{ tech }}</span>
      </div>
    </div>
  </div>
</section>
